contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 x) public {
        require(true);

        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(reverted || (afterSupply + x == beforeSupply && afterSupply >= afterDistributed));
    }
}

