contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 x) internal {
        vm.assume(true);
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        uint256 beforeDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeDistributed = __r; } catch { return; }
        bool reverted;
        try c.burn(x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterSupply;
        try c.totalSupply() returns (uint256 __r) { afterSupply = __r; } catch { return; }
        uint256 afterDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterDistributed = __r; } catch { return; }
        assertTrue(reverted || (afterSupply + x == beforeSupply && afterSupply >= afterDistributed));
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
